<script setup lang="ts">
import {onMounted,ref} from 'vue';import {analyzeLocally,type CvAnalysis} from './services/local-ai';import {enqueue,pending,remove,type PendingApplication} from './services/offline';
const analysis=ref<CvAnalysis>();const selected=ref<File>();const vacancyId=ref('');const unstable=ref(false);const status=ref('');const queue=ref<PendingApplication[]>([]);const busy=ref(false);
class NetworkError extends Error {}
class HttpResponseError extends Error { constructor(readonly status:number){super(`HTTP ${status}`)} }
async function choose(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;selected.value=file;status.value='Analizando 100% en este dispositivo…';analysis.value=await analyzeLocally(file);status.value=analysis.value.valid?'CV válido. Puedes postular.':'No parece un CV estructurado.'}
function payload(){return{vacancyId:vacancyId.value||undefined,channel:'web',applicant:{name:analysis.value?.name,email:analysis.value?.email,phone:analysis.value?.phone},resume:{fileName:selected.value?.name,localValidation:analysis.value,documentType:selected.value?.type}}}
async function send(item:PendingApplication,retries=1){let response:Response|undefined;for(let i=0;i<retries;i++){try{response=await fetch('/api/v1/ingestion/cvs',{method:'POST',headers:{'Content-Type':'application/json','X-Idempotency-Key':item.idempotencyKey,'Idempotency-Key':item.idempotencyKey},body:JSON.stringify(item.payload)})}catch{if(i===retries-1)throw new NetworkError('No se pudo conectar con el servidor');continue}if(response.status!==200&&response.status!==201)throw new HttpResponseError(response.status);await remove(item.id);return}throw new NetworkError('No se pudo conectar con el servidor')}
async function submit(){if(!analysis.value?.valid||busy.value)return;busy.value=true;const key=crypto.randomUUID();const item={id:key,idempotencyKey:key,payload:payload(),createdAt:new Date().toISOString()};try{if(!navigator.onLine){await enqueue(item);status.value='Sin conexión: postulación guardada localmente para sincronizar después.'}else{try{await send(item,unstable.value?3:1);status.value='Postulación recibida correctamente.'}catch(error){if(error instanceof NetworkError){await enqueue(item);status.value='No se pudo conectar: postulación guardada localmente para sincronizar después.'}else if(error instanceof HttpResponseError){status.value=`El servidor rechazó la solicitud (HTTP ${error.status}). No se guardó en la cola local; revisa los datos e inténtalo más tarde.`}else throw error}}}catch{status.value='No pudimos confirmar el resultado. Revisa el estado de la postulación antes de volver a enviarla.'}finally{try{queue.value=await pending()}catch{status.value='Postulación procesada, pero no se pudo actualizar la cola local.'}busy.value=false}}
async function sync(){if(busy.value)return;busy.value=true;let failure:unknown;try{for(const item of await pending()){try{await send(item)}catch(error){failure=error;break}}queue.value=await pending();status.value=failure instanceof HttpResponseError?`El servidor rechazó una solicitud pendiente (HTTP ${failure.status}); sigue guardada localmente.`:failure?'No se pudo conectar; las postulaciones pendientes siguen guardadas localmente.':`Sincronización completada. Pendientes: ${queue.value.length}.`}catch{status.value='No se pudo acceder a la cola local del navegador.'}finally{queue.value=await pending();busy.value=false}}
onMounted(async()=>{queue.value=await pending();window.addEventListener('online',sync)});
</script>
<template><main><header><a class="brand" href="/portal/">TALENTO<span>.</span></a><nav><a href="/erp/">RRHH</a><a href="/bi/">Inteligencia</a></nav></header><section class="hero"><div><small>POSTULACIÓN PRIVADA · OFFLINE-FIRST</small><h1>Tu experiencia merece llegar más lejos.</h1><p>Validamos tu CV en tu dispositivo. Si pierdes conexión, tu postulación queda guardada localmente y se sincroniza después.</p></div><aside><b>01</b><span>Validación local</span><b>02</b><span>Cola local del navegador</span><b>03</b><span>Envío idempotente</span></aside></section><section class="form"><div class="upload"><label>Vacante (UUID opcional)<input v-model="vacancyId" placeholder="ID de la vacante"/></label><label class="drop"><input type="file" accept=".pdf,.txt,image/*,video/*" @change="choose"/><b>Seleccionar CV o Video-CV</b><span>PDF, imagen, texto o video · análisis sin servidor</span></label><div class="analysis" v-if="analysis"><div class="score" :class="{ok:analysis.valid}">{{Math.round(analysis.confidence*100)}}%</div><div><b>{{analysis.valid?'Documento apto':'Revisión necesaria'}}</b><p>{{analysis.explanation}}</p><span v-for="s in analysis.sections" :key="s">✓ {{s}}</span></div></div></div><div class="submit"><label class="toggle"><input type="checkbox" v-model="unstable"/> Simular red inestable: 3 reintentos, misma Idempotency-Key</label><button :disabled="!analysis?.valid||busy" @click="submit">Enviar postulación</button><button class="secondary" :disabled="busy||queue.length===0" @click="sync">Sincronizar cola ({{queue.length}})</button><p role="status" aria-live="polite">{{status}}</p></div></section></main></template>
